/// A player as shown to others.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct PlayerInfo {
    /// `userId`.
    pub user_id: u32,
    /// `name` (1..=24 bytes of UTF-8 without NUL).
    pub name: String,
    /// Rating in the game's category.
    pub rating: u16,
    /// The rating is still provisional.
    pub provisional: bool,
}

impl PlayerInfo {
    fn encoded_len(&self) -> usize {
        7 + 1 + self.name.len()
    }

    fn write<B: BufMut>(&self, out: &mut B) {
        out.put_u32_le(self.user_id);
        wire::put_str8(out, &self.name);
        out.put_u16_le(self.rating);
        out.put_u8(u8::from(self.provisional));
    }
}

/// A move of a game record.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct MoveRec {
    /// Packed move (Move encoding) (0..=32767).
    pub r#move: u16,
    /// Clock time charged for the move after lag compensation (0 for plies 0 and 1).
    pub spent_ms: u32,
    /// Mover's remaining time after the move, increment included.
    pub clock_ms: u32,
}

impl MoveRec {
    fn encoded_len(&self) -> usize {
        10
    }

    fn write<B: BufMut>(&self, out: &mut B) {
        out.put_u16_le(self.r#move);
        out.put_u32_le(self.spent_ms);
        out.put_u32_le(self.clock_ms);
    }
}

/// Rating of one player before and after a rated game.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct RatingChange {
    /// `before`.
    pub before: u16,
    /// `after`.
    pub after: u16,
    /// Rated games in the category, this one included.
    pub games: u32,
    /// The new rating is still provisional.
    pub provisional: bool,
}

impl RatingChange {
    fn encoded_len(&self) -> usize {
        9
    }

    fn write<B: BufMut>(&self, out: &mut B) {
        out.put_u16_le(self.before);
        out.put_u16_le(self.after);
        out.put_u32_le(self.games);
        out.put_u8(u8::from(self.provisional));
    }
}

