/// The defect of a frame whose type byte is not the one expected (`client`: the direction of the
/// expected message).
pub(crate) fn type_defect(first: Option<u8>, client: bool) -> Defect {
    match first.map(MsgType::from_u8) {
        None => Defect::Empty,
        Some(None) => Defect::UnknownType,
        Some(Some(t)) if t.is_client() != client => Defect::WrongDirection,
        Some(Some(_)) => Defect::WrongType,
    }
}

/// `Hello` (0x01, client to server). First message of a connection. Its first five fields (the Hello prefix:
/// type, seq, proto, minor, caps) are frozen for every version, so that any server can read them and answer
/// any client.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct Hello {
    /// 1.
    pub seq: u32,
    /// Major protocol version: 1.
    pub proto: u16,
    /// Highest minor version the client speaks.
    pub minor: u16,
    /// Capabilities the client supports (bit set).
    pub caps: u64,
    /// Client name and version, for the logs ("Scacelith/1.5.0 win64") (0..=48 bytes of UTF-8 without NUL).
    pub client: String,
    /// Session token from the HTTPS login of this server (16..=160 bytes of UTF-8 without NUL).
    pub token: String,
}

impl Message for Hello {
    const TYPE: MsgType = MsgType::Hello;
    const MIN_LEN: usize = 35;
    const MAX_LEN: usize = 227;

    fn encoded_len(&self) -> usize {
        1 + 16 + 1 + self.client.len() + 1 + self.token.len()
    }

    fn validate(&self) -> Result<(), EncodeError> {
        wire::check_str8("Hello", "client", &self.client, 0, 48)?;
        wire::check_str8("Hello", "token", &self.token, 16, 160)?;
        Ok(())
    }

    fn write_fields<B: BufMut>(&self, out: &mut B) {
        out.put_u32_le(self.seq);
        out.put_u16_le(self.proto);
        out.put_u16_le(self.minor);
        out.put_u64_le(self.caps);
        wire::put_str8(out, &self.client);
        wire::put_str8(out, &self.token);
    }

    fn read_fields(r: &mut Reader<'_>) -> Result<Self, DecodeError> {
        Ok(Self {
            seq: r.u32()?,
            proto: r.u16()?,
            minor: r.u16()?,
            caps: r.u64()?,
            client: r.str8("client", 0, 48)?,
            token: r.str8("token", 16, 160)?,
        })
    }
}

/// `C_Ping` (0x02, client to server). Round-trip and clock-offset probe of the client, answered by the server
/// Pong. At most one is answered per 950 ms.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct ClientPing {
    /// Number of the message on its connection: 1 for the Hello, then one more per message.
    pub seq: u32,
    /// `nonce`.
    pub nonce: u32,
}

impl Message for ClientPing {
    const TYPE: MsgType = MsgType::ClientPing;
    const MIN_LEN: usize = 9;
    const MAX_LEN: usize = 9;

    fn encoded_len(&self) -> usize {
        1 + 8
    }

    fn validate(&self) -> Result<(), EncodeError> {
        Ok(())
    }

    fn write_fields<B: BufMut>(&self, out: &mut B) {
        out.put_u32_le(self.seq);
        out.put_u32_le(self.nonce);
    }

    fn read_fields(r: &mut Reader<'_>) -> Result<Self, DecodeError> {
        Ok(Self {
            seq: r.u32()?,
            nonce: r.u32()?,
        })
    }
}

/// `C_Pong` (0x03, client to server). Answer to the server Ping, sent at once (the server measures the
/// latency with it).
#[derive(Clone, Debug, Default, PartialEq)]
pub struct ClientPong {
    /// Number of the message on its connection: 1 for the Hello, then one more per message.
    pub seq: u32,
    /// Nonce of the server Ping.
    pub nonce: u32,
}

