/// `GameSnapshot` (0xa0, server to client). Complete authoritative state of a game: when it starts (both
/// players), after Welcome when activeGame != 0, on Resync, after every MoveRejected, and unsolicited to the
/// opponent when the held clock of a game restored after a restart starts. Clocks are the remaining times at
/// serverTime; the `running` side counts down from there.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct GameSnapshot {
    /// `game` (below 2^53).
    pub game: u64,
    /// Number of the game's last event (MoveMade, GameEvent, GameEnd) included in this state.
    pub gseq: u32,
    /// Official category id, or "custom" (1..=7 bytes of UTF-8 without NUL).
    pub category: String,
    /// `baseMs`.
    pub base_ms: u32,
    /// `incMs`.
    pub inc_ms: u32,
    /// `rated`.
    pub rated: bool,
    /// `white`.
    pub white: PlayerInfo,
    /// `black`.
    pub black: PlayerInfo,
    /// The receiver's colour (White or Black).
    pub you: Color,
    /// `moves` (at most 1200 items).
    pub moves: Vec<MoveRec>,
    /// Side whose clock runs from serverTime (None: no clock runs).
    pub running: Color,
    /// `whiteMs`.
    pub white_ms: u32,
    /// `blackMs`.
    pub black_ms: u32,
    /// `serverTime` (finite).
    pub server_time: f64,
    /// Side with a pending draw offer (None: none).
    pub draw_offer: Color,
    /// `status`.
    pub status: GameStatus,
    /// `reason`.
    pub reason: EndReason,
    /// `whiteConnected`.
    pub white_connected: bool,
    /// `blackConnected`.
    pub black_connected: bool,
    /// Reconnection grace of this game.
    pub grace_ms: u32,
    /// Time left for the next player's first move (plies 0 and 1; 0 otherwise).
    pub first_move_ms: u32,
    /// Server clock (epoch ms) when the game was created (finite).
    pub started_at: f64,
    /// Side with a pending rematch offer (None: none).
    pub rematch: Color,
    /// The robots press the clock by themselves (fixed when the game was created).
    pub auto_press: bool,
}

impl Message for GameSnapshot {
    const TYPE: MsgType = MsgType::GameSnapshot;
    const MIN_LEN: usize = 85;
    const MAX_LEN: usize = 12137;

    fn encoded_len(&self) -> usize {
        1 + 62 + 1 + self.category.len() + self.white.encoded_len() + self.black.encoded_len() + 2 + self.moves.iter().map(|x| x.encoded_len()).sum::<usize>()
    }

    fn validate(&self) -> Result<(), EncodeError> {
        wire::check_id53("GameSnapshot", "game", self.game)?;
        wire::check_str8("GameSnapshot", "category", &self.category, 1, 7)?;
        wire::check_str8("GameSnapshot", "white.name", &self.white.name, 1, 24)?;
        wire::check_str8("GameSnapshot", "black.name", &self.black.name, 1, 24)?;
        wire::check_count16("GameSnapshot", "moves", self.moves.len(), 1200)?;
        for item in &self.moves {
            wire::check_bounds("GameSnapshot", "moves.move", item.r#move, 0, 32767)?;
        }
        wire::check_f64("GameSnapshot", "serverTime", self.server_time)?;
        wire::check_known("GameSnapshot", "reason", self.reason.is_known(), "EndReason")?;
        wire::check_f64("GameSnapshot", "startedAt", self.started_at)?;
        Ok(())
    }

    fn write_fields<B: BufMut>(&self, out: &mut B) {
        out.put_u64_le(self.game);
        out.put_u32_le(self.gseq);
        wire::put_str8(out, &self.category);
        out.put_u32_le(self.base_ms);
        out.put_u32_le(self.inc_ms);
        out.put_u8(u8::from(self.rated));
        self.white.write(out);
        self.black.write(out);
        out.put_u8(self.you.to_u8());
        wire::put_count16(out, self.moves.len());
        for item in &self.moves {
            item.write(out);
        }
        out.put_u8(self.running.to_u8());
        out.put_u32_le(self.white_ms);
        out.put_u32_le(self.black_ms);
        wire::put_f64(out, self.server_time);
        out.put_u8(self.draw_offer.to_u8());
        out.put_u8(self.status.to_u8());
        out.put_u8(self.reason.to_u8());
        out.put_u8(u8::from(self.white_connected));
        out.put_u8(u8::from(self.black_connected));
        out.put_u32_le(self.grace_ms);
        out.put_u32_le(self.first_move_ms);
        wire::put_f64(out, self.started_at);
        out.put_u8(self.rematch.to_u8());
        out.put_u8(u8::from(self.auto_press));
    }

    fn read_fields(r: &mut Reader<'_>) -> Result<Self, DecodeError> {
        Ok(Self {
            game: r.id53("game")?,
            gseq: r.u32()?,
            category: r.str8("category", 1, 7)?,
            base_ms: r.u32()?,
            inc_ms: r.u32()?,
            rated: r.bool("rated")?,
            white: PlayerInfo {
                user_id: r.u32()?,
                name: r.str8("white.name", 1, 24)?,
                rating: r.u16()?,
                provisional: r.bool("white.provisional")?,
            },
            black: PlayerInfo {
                user_id: r.u32()?,
                name: r.str8("black.name", 1, 24)?,
                rating: r.u16()?,
                provisional: r.bool("black.provisional")?,
            },
            you: Color::read(r, "you")?,
            moves: {
                let count = r.count16("moves", 1200, 10)?;
                let mut items = Vec::with_capacity(count);
                for _ in 0..count {
                    items.push(MoveRec {
                        r#move: Reader::bounded(r.u16()?, "moves.move", 0, 32767)?,
                        spent_ms: r.u32()?,
                        clock_ms: r.u32()?,
                    });
                }
                items
            },
            running: Color::read(r, "running")?,
            white_ms: r.u32()?,
            black_ms: r.u32()?,
            server_time: r.f64("serverTime")?,
            draw_offer: Color::read(r, "drawOffer")?,
            status: GameStatus::read(r, "status")?,
            reason: EndReason::read(r, "reason")?,
            white_connected: r.bool("whiteConnected")?,
            black_connected: r.bool("blackConnected")?,
            grace_ms: r.u32()?,
            first_move_ms: r.u32()?,
            started_at: r.f64("startedAt")?,
            rematch: Color::read(r, "rematch")?,
            auto_press: r.bool("autoPress")?,
        })
    }
}

