impl ClientGesture {
    /// The server `Gesture` frame that relays the client frame `frame`: `frame` is validated (it must be a
    /// whole client `Gesture`), then copied without its seq.
    pub fn relay_frame(frame: &[u8]) -> Result<[u8; ServerGesture::MAX_LEN], DecodeError> {
        Self::decode(frame)?;
        let mut out = [0; ServerGesture::MAX_LEN];
        out[0] = MsgType::ServerGesture.to_u8();
        out[1..].copy_from_slice(&frame[5..]);
        Ok(out)
    }
}

/// A client to server message.
#[derive(Clone, Debug, PartialEq)]
pub enum ClientMsg {
    /// [`Hello`].
    Hello(Hello),
    /// [`ClientPing`].
    Ping(ClientPing),
    /// [`ClientPong`].
    Pong(ClientPong),
    /// [`QueueJoin`].
    QueueJoin(QueueJoin),
    /// [`QueueLeave`].
    QueueLeave(QueueLeave),
    /// [`ChallengeCreate`].
    ChallengeCreate(ChallengeCreate),
    /// [`ChallengeAccept`].
    ChallengeAccept(ChallengeAccept),
    /// [`ChallengeDecline`].
    ChallengeDecline(ChallengeDecline),
    /// [`ChallengeCancel`].
    ChallengeCancel(ChallengeCancel),
    /// [`ChallengeJoinCode`].
    ChallengeJoinCode(ChallengeJoinCode),
    /// [`Move`].
    Move(Move),
    /// [`Resign`].
    Resign(Resign),
    /// [`DrawOffer`].
    DrawOffer(DrawOffer),
    /// [`DrawAnswer`].
    DrawAnswer(DrawAnswer),
    /// [`DrawClaim`].
    DrawClaim(DrawClaim),
    /// [`Abort`].
    Abort(Abort),
    /// [`Resync`].
    Resync(Resync),
    /// [`Rematch`].
    Rematch(Rematch),
    /// [`ClientGesture`].
    Gesture(ClientGesture),
}

impl ClientMsg {
    /// Strict decoding (the server's): unknown types, server types, truncation, trailing bytes and
    /// every value outside its bounds are refused.
    pub fn decode(buf: &[u8]) -> Result<Self, DecodeError> {
        let mut r = Reader::new(buf, true);
        let msg = match buf.first().copied() {
            Some(0x01) => Self::Hello(Hello::read_fields(&mut r)?),
            Some(0x02) => Self::Ping(ClientPing::read_fields(&mut r)?),
            Some(0x03) => Self::Pong(ClientPong::read_fields(&mut r)?),
            Some(0x10) => Self::QueueJoin(QueueJoin::read_fields(&mut r)?),
            Some(0x11) => Self::QueueLeave(QueueLeave::read_fields(&mut r)?),
            Some(0x12) => Self::ChallengeCreate(ChallengeCreate::read_fields(&mut r)?),
            Some(0x13) => Self::ChallengeAccept(ChallengeAccept::read_fields(&mut r)?),
            Some(0x14) => Self::ChallengeDecline(ChallengeDecline::read_fields(&mut r)?),
            Some(0x15) => Self::ChallengeCancel(ChallengeCancel::read_fields(&mut r)?),
            Some(0x16) => Self::ChallengeJoinCode(ChallengeJoinCode::read_fields(&mut r)?),
            Some(0x20) => Self::Move(Move::read_fields(&mut r)?),
            Some(0x21) => Self::Resign(Resign::read_fields(&mut r)?),
            Some(0x22) => Self::DrawOffer(DrawOffer::read_fields(&mut r)?),
            Some(0x23) => Self::DrawAnswer(DrawAnswer::read_fields(&mut r)?),
            Some(0x24) => Self::DrawClaim(DrawClaim::read_fields(&mut r)?),
            Some(0x25) => Self::Abort(Abort::read_fields(&mut r)?),
            Some(0x26) => Self::Resync(Resync::read_fields(&mut r)?),
            Some(0x27) => Self::Rematch(Rematch::read_fields(&mut r)?),
            Some(0x28) => Self::Gesture(ClientGesture::read_fields(&mut r)?),
            first => return Err(DecodeError::new(type_defect(first, true), "")),
        };
        r.finish()?;
        Ok(msg)
    }

    /// Type of the message.
    pub fn msg_type(&self) -> MsgType {
        match self {
            Self::Hello(_) => MsgType::Hello,
            Self::Ping(_) => MsgType::ClientPing,
            Self::Pong(_) => MsgType::ClientPong,
            Self::QueueJoin(_) => MsgType::QueueJoin,
            Self::QueueLeave(_) => MsgType::QueueLeave,
            Self::ChallengeCreate(_) => MsgType::ChallengeCreate,
            Self::ChallengeAccept(_) => MsgType::ChallengeAccept,
            Self::ChallengeDecline(_) => MsgType::ChallengeDecline,
            Self::ChallengeCancel(_) => MsgType::ChallengeCancel,
            Self::ChallengeJoinCode(_) => MsgType::ChallengeJoinCode,
            Self::Move(_) => MsgType::Move,
            Self::Resign(_) => MsgType::Resign,
            Self::DrawOffer(_) => MsgType::DrawOffer,
            Self::DrawAnswer(_) => MsgType::DrawAnswer,
            Self::DrawClaim(_) => MsgType::DrawClaim,
            Self::Abort(_) => MsgType::Abort,
            Self::Resync(_) => MsgType::Resync,
            Self::Rematch(_) => MsgType::Rematch,
            Self::Gesture(_) => MsgType::ClientGesture,
        }
    }

    /// `seq` of the message.
    pub fn seq(&self) -> u32 {
        match self {
            Self::Hello(m) => m.seq,
            Self::Ping(m) => m.seq,
            Self::Pong(m) => m.seq,
            Self::QueueJoin(m) => m.seq,
            Self::QueueLeave(m) => m.seq,
            Self::ChallengeCreate(m) => m.seq,
            Self::ChallengeAccept(m) => m.seq,
            Self::ChallengeDecline(m) => m.seq,
            Self::ChallengeCancel(m) => m.seq,
            Self::ChallengeJoinCode(m) => m.seq,
            Self::Move(m) => m.seq,
            Self::Resign(m) => m.seq,
            Self::DrawOffer(m) => m.seq,
            Self::DrawAnswer(m) => m.seq,
            Self::DrawClaim(m) => m.seq,
            Self::Abort(m) => m.seq,
            Self::Resync(m) => m.seq,
            Self::Rematch(m) => m.seq,
            Self::Gesture(m) => m.seq,
        }
    }

    /// Encoded size, type byte included.
    pub fn encoded_len(&self) -> usize {
        match self {
            Self::Hello(m) => m.encoded_len(),
            Self::Ping(m) => m.encoded_len(),
            Self::Pong(m) => m.encoded_len(),
            Self::QueueJoin(m) => m.encoded_len(),
            Self::QueueLeave(m) => m.encoded_len(),
            Self::ChallengeCreate(m) => m.encoded_len(),
            Self::ChallengeAccept(m) => m.encoded_len(),
            Self::ChallengeDecline(m) => m.encoded_len(),
            Self::ChallengeCancel(m) => m.encoded_len(),
            Self::ChallengeJoinCode(m) => m.encoded_len(),
            Self::Move(m) => m.encoded_len(),
            Self::Resign(m) => m.encoded_len(),
            Self::DrawOffer(m) => m.encoded_len(),
            Self::DrawAnswer(m) => m.encoded_len(),
            Self::DrawClaim(m) => m.encoded_len(),
            Self::Abort(m) => m.encoded_len(),
            Self::Resync(m) => m.encoded_len(),
            Self::Rematch(m) => m.encoded_len(),
            Self::Gesture(m) => m.encoded_len(),
        }
    }

    /// Encodes the message (see [`Message::encode`]).
    pub fn encode<B: BufMut>(&self, out: &mut B) -> Result<(), EncodeError> {
        match self {
            Self::Hello(m) => m.encode(out),
            Self::Ping(m) => m.encode(out),
            Self::Pong(m) => m.encode(out),
            Self::QueueJoin(m) => m.encode(out),
            Self::QueueLeave(m) => m.encode(out),
            Self::ChallengeCreate(m) => m.encode(out),
            Self::ChallengeAccept(m) => m.encode(out),
            Self::ChallengeDecline(m) => m.encode(out),
            Self::ChallengeCancel(m) => m.encode(out),
            Self::ChallengeJoinCode(m) => m.encode(out),
            Self::Move(m) => m.encode(out),
            Self::Resign(m) => m.encode(out),
            Self::DrawOffer(m) => m.encode(out),
            Self::DrawAnswer(m) => m.encode(out),
            Self::DrawClaim(m) => m.encode(out),
            Self::Abort(m) => m.encode(out),
            Self::Resync(m) => m.encode(out),
            Self::Rematch(m) => m.encode(out),
            Self::Gesture(m) => m.encode(out),
        }
    }

    /// The encoded message in a buffer of the exact size.
    pub fn to_bytes(&self) -> Result<bytes::Bytes, EncodeError> {
        let mut out = bytes::BytesMut::with_capacity(self.encoded_len());
        self.encode(&mut out)?;
        Ok(out.freeze())
    }
}

