/// A server to client message.
#[derive(Clone, Debug, PartialEq)]
pub enum ServerMsg {
    /// [`Welcome`].
    Welcome(Welcome),
    /// [`Error`].
    Error(Error),
    /// [`ServerPing`].
    Ping(ServerPing),
    /// [`ServerPong`].
    Pong(ServerPong),
    /// [`Ack`].
    Ack(Ack),
    /// [`Notice`].
    Notice(Notice),
    /// [`QueueStatus`].
    QueueStatus(QueueStatus),
    /// [`ChallengeReceived`].
    ChallengeReceived(ChallengeReceived),
    /// [`ChallengeStatus`].
    ChallengeStatus(ChallengeStatus),
    /// [`GameSnapshot`].
    GameSnapshot(GameSnapshot),
    /// [`MoveMade`].
    MoveMade(MoveMade),
    /// [`MoveRejected`].
    MoveRejected(MoveRejected),
    /// [`GameEvent`].
    GameEvent(GameEvent),
    /// [`GameEnd`].
    GameEnd(GameEnd),
    /// [`RatingUpdate`].
    RatingUpdate(RatingUpdate),
    /// [`ServerGesture`].
    Gesture(ServerGesture),
}

impl ServerMsg {
    /// Lenient decoding (the clients'): `Ok(None)` for a message to ignore (a type this codec does
    /// not know as a server message), trailing bytes ignored (fields of a later minor), unknown
    /// values of open enums kept as `Unknown`. Anything else outside the rules is refused.
    pub fn decode(buf: &[u8]) -> Result<Option<Self>, DecodeError> {
        Self::decode_with(buf, false)
    }

    /// Strict decoding: the message must be exactly one of this minor (tests of a server).
    pub fn decode_exact(buf: &[u8]) -> Result<Self, DecodeError> {
        Self::decode_with(buf, true)?.ok_or(DecodeError::new(Defect::UnknownType, ""))
    }

    fn decode_with(buf: &[u8], strict: bool) -> Result<Option<Self>, DecodeError> {
        let mut r = Reader::new(buf, strict);
        let msg = match buf.first().copied() {
            Some(0x80) => Self::Welcome(Welcome::read_fields(&mut r)?),
            Some(0x81) => Self::Error(Error::read_fields(&mut r)?),
            Some(0x82) => Self::Ping(ServerPing::read_fields(&mut r)?),
            Some(0x83) => Self::Pong(ServerPong::read_fields(&mut r)?),
            Some(0x84) => Self::Ack(Ack::read_fields(&mut r)?),
            Some(0x85) => Self::Notice(Notice::read_fields(&mut r)?),
            Some(0x90) => Self::QueueStatus(QueueStatus::read_fields(&mut r)?),
            Some(0x91) => Self::ChallengeReceived(ChallengeReceived::read_fields(&mut r)?),
            Some(0x92) => Self::ChallengeStatus(ChallengeStatus::read_fields(&mut r)?),
            Some(0xa0) => Self::GameSnapshot(GameSnapshot::read_fields(&mut r)?),
            Some(0xa1) => Self::MoveMade(MoveMade::read_fields(&mut r)?),
            Some(0xa2) => Self::MoveRejected(MoveRejected::read_fields(&mut r)?),
            Some(0xa3) => Self::GameEvent(GameEvent::read_fields(&mut r)?),
            Some(0xa4) => Self::GameEnd(GameEnd::read_fields(&mut r)?),
            Some(0xa5) => Self::RatingUpdate(RatingUpdate::read_fields(&mut r)?),
            Some(0xa6) => Self::Gesture(ServerGesture::read_fields(&mut r)?),
            None => return Err(DecodeError::new(Defect::Empty, "")),
            Some(_) if !strict => return Ok(None),
            first => return Err(DecodeError::new(type_defect(first, false), "")),
        };
        r.finish()?;
        Ok(Some(msg))
    }

    /// Type of the message.
    pub fn msg_type(&self) -> MsgType {
        match self {
            Self::Welcome(_) => MsgType::Welcome,
            Self::Error(_) => MsgType::Error,
            Self::Ping(_) => MsgType::ServerPing,
            Self::Pong(_) => MsgType::ServerPong,
            Self::Ack(_) => MsgType::Ack,
            Self::Notice(_) => MsgType::Notice,
            Self::QueueStatus(_) => MsgType::QueueStatus,
            Self::ChallengeReceived(_) => MsgType::ChallengeReceived,
            Self::ChallengeStatus(_) => MsgType::ChallengeStatus,
            Self::GameSnapshot(_) => MsgType::GameSnapshot,
            Self::MoveMade(_) => MsgType::MoveMade,
            Self::MoveRejected(_) => MsgType::MoveRejected,
            Self::GameEvent(_) => MsgType::GameEvent,
            Self::GameEnd(_) => MsgType::GameEnd,
            Self::RatingUpdate(_) => MsgType::RatingUpdate,
            Self::Gesture(_) => MsgType::ServerGesture,
        }
    }

    /// Encoded size, type byte included.
    pub fn encoded_len(&self) -> usize {
        match self {
            Self::Welcome(m) => m.encoded_len(),
            Self::Error(m) => m.encoded_len(),
            Self::Ping(m) => m.encoded_len(),
            Self::Pong(m) => m.encoded_len(),
            Self::Ack(m) => m.encoded_len(),
            Self::Notice(m) => m.encoded_len(),
            Self::QueueStatus(m) => m.encoded_len(),
            Self::ChallengeReceived(m) => m.encoded_len(),
            Self::ChallengeStatus(m) => m.encoded_len(),
            Self::GameSnapshot(m) => m.encoded_len(),
            Self::MoveMade(m) => m.encoded_len(),
            Self::MoveRejected(m) => m.encoded_len(),
            Self::GameEvent(m) => m.encoded_len(),
            Self::GameEnd(m) => m.encoded_len(),
            Self::RatingUpdate(m) => m.encoded_len(),
            Self::Gesture(m) => m.encoded_len(),
        }
    }

    /// Encodes the message (see [`Message::encode`]).
    pub fn encode<B: BufMut>(&self, out: &mut B) -> Result<(), EncodeError> {
        match self {
            Self::Welcome(m) => m.encode(out),
            Self::Error(m) => m.encode(out),
            Self::Ping(m) => m.encode(out),
            Self::Pong(m) => m.encode(out),
            Self::Ack(m) => m.encode(out),
            Self::Notice(m) => m.encode(out),
            Self::QueueStatus(m) => m.encode(out),
            Self::ChallengeReceived(m) => m.encode(out),
            Self::ChallengeStatus(m) => m.encode(out),
            Self::GameSnapshot(m) => m.encode(out),
            Self::MoveMade(m) => m.encode(out),
            Self::MoveRejected(m) => m.encode(out),
            Self::GameEvent(m) => m.encode(out),
            Self::GameEnd(m) => m.encode(out),
            Self::RatingUpdate(m) => m.encode(out),
            Self::Gesture(m) => m.encode(out),
        }
    }

    /// The encoded message in a buffer of the exact size.
    pub fn to_bytes(&self) -> Result<bytes::Bytes, EncodeError> {
        let mut out = bytes::BytesMut::with_capacity(self.encoded_len());
        self.encode(&mut out)?;
        Ok(out.freeze())
    }
}

